func (q *Queries) ListAllVouStorageKeys(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, listAllVouStorageKeys)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var storage_key string
		if err := rows.Scan(&storage_key); err != nil {
			return nil, err
		}
		items = append(items, storage_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

