const listVouDocuments = `-- name: ListVouDocuments :many
SELECT d.id, d.entity, d.document_no, d.status, d.revision, d.business_date, d.currency, d.total_amount_cents, d.remark, d.created_at, d.created_by, d.updated_at, d.updated_by, d.reviewed_at, d.reviewed_by, d.approved_at, d.approved_by, d.checked_at, d.checked_by, d.parent_document_id, d.parent_entity, d.due_date, d.posted_at, d.posted_by,
       COALESCE(so.customer_name, sob.customer_name, sd.customer_name, ss.customer_name, sr.customer_name,
                pqi.supplier_name, po.supplier_name, pi.supplier_name, pr.supplier_name, r.counterparty_name,
                p.counterparty_name, er.employee_name, ep.employee_name, elw.employee_name, oi.counterparty_name,
                aa.supplier_name, asl.counterparty_name, bd.counterparty_name, oi.source_name, '') AS party_name
FROM vou_documents d
LEFT JOIN vou_sale_order_details so ON so.document_id = d.id
LEFT JOIN vou_sale_outbound_details sob ON sob.document_id = d.id
LEFT JOIN vou_sale_delivery_details sd ON sd.document_id = d.id
LEFT JOIN vou_sale_signoff_details ss ON ss.document_id = d.id
LEFT JOIN vou_sale_return_details sr ON sr.document_id = d.id
LEFT JOIN vou_purchase_inquiry_details pqi ON pqi.document_id = d.id
LEFT JOIN vou_purchase_order_details po ON po.document_id = d.id
LEFT JOIN vou_purchase_inbound_details pi ON pi.document_id = d.id
LEFT JOIN vou_purchase_return_details pr ON pr.document_id = d.id
LEFT JOIN vou_receipt_details r ON r.document_id = d.id
LEFT JOIN vou_payment_details p ON p.document_id = d.id
LEFT JOIN vou_expense_reimbursement_details er ON er.document_id = d.id
LEFT JOIN vou_expense_payment_details ep ON ep.document_id = d.id
LEFT JOIN vou_employee_loan_writeoff_details elw ON elw.document_id = d.id
LEFT JOIN vou_other_income_details oi ON oi.document_id = d.id
LEFT JOIN vou_asset_acquisition_details aa ON aa.document_id = d.id
LEFT JOIN vou_asset_sale_details asl ON asl.document_id = d.id
LEFT JOIN vou_bill_details bd ON bd.document_id = d.id
WHERE d.entity = $1
  AND (COALESCE(cardinality($2::text[]), 0) = 0 OR d.status = ANY($2::text[]))
  AND ($3::date IS NULL OR d.business_date >= $3::date)
  AND ($4::date IS NULL OR d.business_date <= $4::date)
  AND (
      $5::text = ''
      OR so.customer_object_id = $5
      OR sob.customer_object_id = $5
      OR sd.customer_object_id = $5
      OR ss.customer_object_id = $5
      OR sr.customer_object_id = $5
      OR po.supplier_object_id = $5
      OR pi.supplier_object_id = $5
      OR pr.supplier_object_id = $5
      OR r.counterparty_object_id = $5
      OR p.counterparty_object_id = $5
      OR ep.employee_object_id = $5
      OR elw.employee_object_id = $5
      OR oi.counterparty_object_id = $5
      OR aa.supplier_object_id = $5
      OR asl.counterparty_object_id = $5
      OR bd.counterparty_object_id = $5
  )
  AND (
      $6::text = ''
      OR d.document_no ILIKE '%' || $6 || '%'
      OR so.customer_code ILIKE '%' || $6 || '%' OR so.customer_name ILIKE '%' || $6 || '%'
      OR sob.customer_code ILIKE '%' || $6 || '%' OR sob.customer_name ILIKE '%' || $6 || '%'
      OR sd.customer_code ILIKE '%' || $6 || '%' OR sd.customer_name ILIKE '%' || $6 || '%'
      OR ss.customer_code ILIKE '%' || $6 || '%' OR ss.customer_name ILIKE '%' || $6 || '%'
      OR sr.customer_code ILIKE '%' || $6 || '%' OR sr.customer_name ILIKE '%' || $6 || '%'
      OR po.supplier_code ILIKE '%' || $6 || '%' OR po.supplier_name ILIKE '%' || $6 || '%'
      OR pi.supplier_code ILIKE '%' || $6 || '%' OR pi.supplier_name ILIKE '%' || $6 || '%'
      OR pr.supplier_code ILIKE '%' || $6 || '%' OR pr.supplier_name ILIKE '%' || $6 || '%'
      OR r.counterparty_code ILIKE '%' || $6 || '%' OR r.counterparty_name ILIKE '%' || $6 || '%'
      OR p.counterparty_code ILIKE '%' || $6 || '%' OR p.counterparty_name ILIKE '%' || $6 || '%'
      OR ep.employee_code ILIKE '%' || $6 || '%' OR ep.employee_name ILIKE '%' || $6 || '%'
      OR elw.employee_code ILIKE '%' || $6 || '%' OR elw.employee_name ILIKE '%' || $6 || '%'
      OR oi.source_name ILIKE '%' || $6 || '%' OR oi.counterparty_name ILIKE '%' || $6 || '%'
      OR aa.supplier_code ILIKE '%' || $6 || '%' OR aa.supplier_name ILIKE '%' || $6 || '%'
      OR asl.counterparty_code ILIKE '%' || $6 || '%' OR asl.counterparty_name ILIKE '%' || $6 || '%'
      OR bd.counterparty_code ILIKE '%' || $6 || '%' OR bd.counterparty_name ILIKE '%' || $6 || '%'
  )
ORDER BY
  CASE WHEN $7::text = 'updatedAt' AND $8::text = 'asc' THEN d.updated_at END ASC,
  CASE WHEN $7::text = 'updatedAt' AND $8::text = 'desc' THEN d.updated_at END DESC,
  CASE WHEN $7::text = 'documentNo' AND $8::text = 'asc' THEN d.document_no END ASC,
  CASE WHEN $7::text = 'documentNo' AND $8::text = 'desc' THEN d.document_no END DESC,
  CASE WHEN $7::text = 'businessDate' AND $8::text = 'asc' THEN d.business_date END ASC,
  CASE WHEN $7::text = 'businessDate' AND $8::text = 'desc' THEN d.business_date END DESC,
  CASE WHEN $7::text = 'status' AND $8::text = 'asc' THEN d.status END ASC,
  CASE WHEN $7::text = 'status' AND $8::text = 'desc' THEN d.status END DESC,
  CASE WHEN $7::text = 'amount' AND $8::text = 'asc' THEN d.total_amount_cents END ASC,
  CASE WHEN $7::text = 'amount' AND $8::text = 'desc' THEN d.total_amount_cents END DESC,
  d.id DESC
LIMIT $10 OFFSET $9
`

